import{_ as t,o as a,c as d,a2 as n}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Day05 · First run, entrances, and mail closure","description":"","frontmatter":{"title":"Day05 · First run, entrances, and mail closure","outline":false},"headers":[],"relativePath":"en/log/day-05.md","filePath":"en/log/day-05.md","lastUpdated":null}'),o={name:"en/log/day-05.md"};function r(s,e,i,c,l,u){return a(),d("div",null,[...e[0]||(e[0]=[n('<p>2026-11-08 was the day Hearth turned existing capabilities into entrances. 40 commits touched 91 files (+9,076/−329): the morning closed gaps in model profiles, routing, chat startup, and executor readiness, then fixed behaviour with a repeatable browser E2E; later, methods advanced to an auditable schema-11 application, and first run, proactive reminders, memory recall, the Feishu long connection, and SMTP/IMAP mail were wired into real interfaces. The suite grew from 54 test files and 296 tests on Day04 to 61 files and 381 tests.</p><p>The theme was not another page. It was making existing closures reachable for a new user, answerable from a phone approval, and verifiable with a real mail account. Every step kept the same boundary: notifications only make a person aware; approval still goes through one approval and effect ledger; without a real account, delivery and receipts are never fabricated.</p><h2 id="early-morning-fix-the-loop-then-pin-acceptance" tabindex="-1">Early morning: fix the loop, then pin acceptance <a class="header-anchor" href="#early-morning-fix-the-loop-then-pin-acceptance" aria-label="Permalink to &quot;Early morning: fix the loop, then pin acceptance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Model profiles and keys</td><td>Clear the chat-profile pointer before deleting a profile; write an empty API-key cipher when the key is cleared so the old secret cannot revive; registry validation failures return 4xx instead of 500</td></tr><tr><td>Readiness</td><td><code>native</code>, Codex, and DeepSeek Harness derive readiness from the model binding used at execution time, and the UI, router, and scheduler share one health result</td></tr><tr><td>Chat startup</td><td>New chats load server defaults before enabling the composer; stale or deleted conversations recover; Enter during IME composition no longer sends a message</td></tr><tr><td>Settings persistence</td><td>Blank executor commands or paths count as unconfigured, so saving no longer fails or erases stored values; approval and routing settings load before saving; sidebar readiness and executor labels match runtime state</td></tr><tr><td>Scheduler recovery</td><td>Queued tasks stay recoverable when an executor is unavailable, and scheduling errors are contained so an unavailable executor cannot crash the server</td></tr><tr><td>Browser E2E</td><td>A repeatable E2E runs in an isolated data directory and covers first run, live chat, tasks, conversation switching and recovery, model-key masking/clearing, executor settings, narrow viewports, and console errors; offline mode skips scenarios that need a live model</td></tr></tbody></table><h2 id="skills-methods-become-auditable-execution-input" tabindex="-1">Skills: methods become auditable execution input <a class="header-anchor" href="#skills-methods-become-auditable-execution-input" aria-label="Permalink to &quot;Skills: methods become auditable execution input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Schema 11</td><td>Adds a <code>method_applications</code> audit table, task method pins, and candidate generation/fingerprint columns; a migration test preserves tasks, runs, and checkpoints from older databases</td></tr><tr><td>Method context</td><td>Method guidance renders as bounded, untrusted blocks; pinned and template methods resolve deterministically; an application is recorded only when the block actually enters the prompt</td></tr><tr><td>Execution injection</td><td>Selected methods flow into task, cross-executor handoff, and repair prompts; no application record is written when the block is absent, so audit and execution cannot disagree</td></tr><tr><td>Evidence gate</td><td>Baseline and trial samples pair by template, and at least two baseline plus two trial tasks are required before a verdict can improve; a trial must match the per-run application and version and must not already belong to another method</td></tr><tr><td>Generations and rollback</td><td>Adopted methods promote into numbered generations that supersede earlier ones; rolling back a newer generation restores the previous one instead of leaving a single mutable state</td></tr><tr><td>Candidates and auto-learn</td><td>Ordered tools, decisions, and artifacts are extracted from the context ledger; candidates merge by fingerprint with one source task; a method-learning switch lets terminal tasks best-effort generate candidates and record trial evidence</td></tr><tr><td>Skills surface</td><td>The methods page is presented as &quot;Skills&quot;, navigation is restored, and generation, auto-learn settings, trial-task creation, paired evaluation, application audit, and generation rollback are exposed</td></tr></tbody></table><h2 id="late-morning-first-run-reminders-and-memory" tabindex="-1">Late morning: first run, reminders, and memory <a class="header-anchor" href="#late-morning-first-run-reminders-and-memory" aria-label="Permalink to &quot;Late morning: first run, reminders, and memory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>First-run API</td><td>Adds first-run state and readiness checks; onboarding is required only when no state exists and no chat model is configured, with separate completed, skipped, and reset states</td></tr><tr><td>Four-step wizard</td><td><code>/welcome</code> connects provider selection, connection test, executor check, memory and proactive preferences, and entry into chat; saving a model creates the profile, sets the chat model, and binds the native executor in one step</td></tr><tr><td>Navigation and reminders</td><td>Primary navigation exposes &quot;Needs you&quot;, &quot;Memory&quot;, &quot;Skills&quot;, and &quot;Mail&quot;; a notification centre turns pending approvals and proactive suggestions into readable reminders, with in-app toasts and optional browser desktop notifications while the page is open</td></tr><tr><td>Proactive scan</td><td>The service scans once after startup and every five minutes afterwards; task, approval, effect, and source changes trigger a debounced scan after two seconds, still subject to enablement, proactive level, daily cap, quiet hours, cooldown, and dedupe</td></tr><tr><td>Delivery semantics</td><td>A suggestion emits <code>delivered</code> only when it is actually delivered; nothing is promised after the page closes, and without a channel the system falls back to in-app &quot;Needs you&quot;; Feishu messages and desktop notifications never change authority</td></tr><tr><td>Memory recall</td><td>Direct chat recalls relevant memories per conversation and reports the count through an SSE <code>memory</code> event; recall failure never blocks the answer; capture happens only at terminal task states so intermediate states are not written repeatedly</td></tr></tbody></table><h2 id="feishu-and-real-mail" tabindex="-1">Feishu and real mail <a class="header-anchor" href="#feishu-and-real-mail" aria-label="Permalink to &quot;Feishu and real mail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Feishu long connection</td><td>A self-built-app long-connection gateway with tenant-token caching, event parsing, image/file download, reconnect, open_id allowlist, and connection status; no public callback URL is required</td></tr><tr><td>Tasks and approvals</td><td>Task state and one-time approval summaries go to mapped conversations; <code>/approve</code> and <code>/reject</code> accept only allowlisted open_ids and match approval prefixes among tasks in the current conversation; rejection produces no external effect</td></tr><tr><td>Feishu settings</td><td>Settings gains App ID/Secret (encrypted), allowlist, Feishu/Lark domain, enablement, and connection status</td></tr><tr><td>Mail accounts</td><td>SMTP/IMAP host, port, TLS, account, and password are stored locally; passwords are AES-256-GCM encrypted and a blank edit preserves the old one; connection test, update, and delete are supported</td></tr><tr><td>SMTP send</td><td>Choosing an SMTP account on an outbox draft creates a one-time <code>email.smtp-send</code> approval with a preview of sender, recipients, cc/bcc, subject, body, and the no-recall impact; the TTL is ten minutes and the effect ledger sends after approval and stores <code>receipt.json</code></td></tr><tr><td>Idempotency and uncertainty</td><td>Sending reuses the approval parameter hash, effect idempotency key, deterministic Message-ID, and local receipt; a <code>sending.json</code> placeholder is written first, and a directory without a receipt becomes an uncertain state rather than a blind resend</td></tr><tr><td>IMAP sync</td><td>Opens INBOX read-only and reads the latest 20–50 messages without marking them read; Message-ID deduplicates into Sources and bodies enter the source content directory; sync defaults to 15 minutes and can be disabled per account</td></tr><tr><td>Mail workspace</td><td>Accounts, inbox, and compose views; the inbox reads synced source items, compose only creates a draft, and the approval card shows a mail preview; this version has no attachment picker UI</td></tr></tbody></table><h2 id="documentation-and-delivery-status" tabindex="-1">Documentation and delivery status <a class="header-anchor" href="#documentation-and-delivery-status" aria-label="Permalink to &quot;Documentation and delivery status&quot;">​</a></h2><p>The English and Chinese READMEs, delivery status, and the control, effects, and experience design pages now record first run, the proactive loop, the Feishu long connection, and real mail. Delivery status updates the verification baseline to 61 test files and 381 tests and keeps real accounts, bounce semantics, and attachment UI explicitly unaccepted. This log also updates the site home, navigation, sidebar, documentation map, and the implementation link in delivery status.</p><h2 id="verification-baseline" tabindex="-1">Verification baseline <a class="header-anchor" href="#verification-baseline" aria-label="Permalink to &quot;Verification baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Tests</td><td><code>npm test</code> passed 61 test files and 381 tests; during the first parallel run the onboarding API case once hit the 5-second timeout, while both the single test and the full rerun passed</td></tr><tr><td>Types</td><td><code>npm run typecheck</code> passed</td></tr><tr><td>Web build</td><td><code>npm run build</code> passed</td></tr><tr><td>Docs build</td><td><code>npm run docs:build</code> passed</td></tr><tr><td>Browser E2E</td><td>Offline <code>npm run test:e2e</code> passed 13 checks; scenarios needing a live model or executor were skipped by design among the 16 cases</td></tr><tr><td>Data migration</td><td>SQLite schema advanced to 11; the migration test passes without losing tasks, runs, or checkpoints</td></tr><tr><td>Real tasks</td><td>Stage-one acceptance still stands: 15 tasks ran, 13 passed; the T07/T08 boundaries are unchanged</td></tr><tr><td>Evidence rule</td><td>Code closure was not written up as real acceptance; notification delivery, a Feishu tenant, and mail receipts were not described as accepted</td></tr></tbody></table><blockquote><p>This log records implementation and internal verification, not a v1.0 release. Real accounts, real devices, long-running operation, and failure drills for phases 2–6 remain governed by <a href="/hearth-os/en/delivery/status.html">delivery status</a>.</p></blockquote><h2 id="commits" tabindex="-1">Commits <a class="header-anchor" href="#commits" aria-label="Permalink to &quot;Commits&quot;">​</a></h2><h3 id="_2026-11-08-40-commits" tabindex="-1">2026-11-08 (40 commits) <a class="header-anchor" href="#_2026-11-08-40-commits" aria-label="Permalink to &quot;2026-11-08 (40 commits)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Commit</th><th>Author</th><th>Changes</th></tr></thead><tbody><tr><td><code>2826b28</code></td><td>JasonBuildAI</td><td>Cleared the chat-profile pointer before deleting a model profile and wrote an empty API-key cipher on update so the old secret cannot revive; 4 files (+60/−2).</td></tr><tr><td><code>58d5831</code></td><td>JasonBuildAI</td><td>Mapped model-registry validation failures to 4xx so <code>PUT /api/model-settings</code> no longer leaks a 500; 2 files (+34/−2).</td></tr><tr><td><code>74c7f2a</code></td><td>JasonBuildAI</td><td>Kept method questions in chat, sent attachment messages to a task executor, and honoured per-message settings on existing conversations without persisting them; 4 files (+136/−4).</td></tr><tr><td><code>0e6f982</code></td><td>JasonBuildAI</td><td>Derived <code>native</code>, Codex, and DeepSeek Harness readiness from the binding used at execution time so the UI, router, and scheduler agree; 5 files (+153/−13).</td></tr><tr><td><code>b92fcee</code></td><td>JasonBuildAI</td><td>Treated blank executor commands or paths as unconfigured so saving no longer fails or erases values, and served new-chat defaults from the server; 4 files (+55/−4).</td></tr><tr><td><code>3294a00</code></td><td>JasonBuildAI</td><td>Loaded server defaults before enabling the composer, recovered stale or deleted conversations, and ignored Enter during IME composition; 2 files (+60/−29).</td></tr><tr><td><code>c0e6883</code></td><td>JasonBuildAI</td><td>Loaded approval and routing settings before saving executors, omitted blank fields, derived sidebar state from executor health, and added the DeepSeek Harness label; 6 files (+38/−8).</td></tr><tr><td><code>9c8a630</code></td><td>JasonBuildAI</td><td>Kept queued tasks recoverable when an executor is unavailable and contained scheduling errors so an unavailable executor cannot crash the server; 4 files (+37/−5).</td></tr><tr><td><code>907d036</code></td><td>JasonBuildAI</td><td>Added a chat-routing test for a bound Codex executor so readiness no longer causes a reroute; 1 file (+39).</td></tr><tr><td><code>149e7c9</code></td><td>JasonBuildAI</td><td>Added a repeatable browser E2E in an isolated data directory covering live chat, tasks, settings, conversation recovery, model-key masking/clearing, readiness, and narrow viewports; refreshed the documented baseline; 6 files (+533/−6).</td></tr><tr><td><code>d484a40</code></td><td>JasonBuildAI</td><td>Disabled global executor detection in offline E2E and skipped task scenarios without a live model or executor so offline runs stay deterministic; 1 file (+5/−4).</td></tr><tr><td><code>70757bf</code></td><td>JasonBuildAI</td><td>Added shared types for method applications, adoption generations, task method pins, and the method context kind; 3 files (+28/−2).</td></tr><tr><td><code>a6a4717</code></td><td>JasonBuildAI</td><td>Added schema 11 with a method-application audit table, task method pins, and candidate generation/fingerprint columns, plus an older-database migration test; 3 files (+130/−12).</td></tr><tr><td><code>d4de771</code></td><td>JasonBuildAI</td><td>Allowed an explicit method pin at task creation and added a task method assignment API with template and status validation; 5 files (+112/−2).</td></tr><tr><td><code>3c59aae</code></td><td>JasonBuildAI</td><td>Rendered method guidance as bounded untrusted blocks, resolved pinned or template methods deterministically, and recorded an application only when included; 4 files (+172/−2).</td></tr><tr><td><code>0cc5d10</code></td><td>JasonBuildAI</td><td>Injected selected methods into task, cross-executor handoff, and repair prompts, and skipped application records when the block was absent; 7 files (+161/−15).</td></tr><tr><td><code>9bbe8b1</code></td><td>JasonBuildAI</td><td>Rejected trial evidence unless it matched the per-run method application and version and the task had not been trialed by another method; 3 files (+62/−2).</td></tr><tr><td><code>739ea83</code></td><td>JasonBuildAI</td><td>Paired baseline and trial samples by template, recorded trial and prompt evidence, and required two baseline plus two trial tasks before a verdict could improve; 4 files (+125/−25).</td></tr><tr><td><code>8889a95</code></td><td>JasonBuildAI</td><td>Promoted adopted methods into numbered generations that supersede earlier ones and restored the previous generation when a newer one was rolled back; 2 files (+80/−9).</td></tr><tr><td><code>4ac17b4</code></td><td>JasonBuildAI</td><td>Extracted ordered tools, decisions, and artifacts from the context ledger, merged candidates by fingerprint, and kept a single source task; 2 files (+79/−19).</td></tr><tr><td><code>08b016c</code></td><td>JasonBuildAI</td><td>Persisted the method-learning switch in app settings and exposed it through the method snapshot and settings APIs; 3 files (+70/−2).</td></tr><tr><td><code>20d7110</code></td><td>JasonBuildAI</td><td>Best-effort generated candidates for completed or failed tasks without a bound method, recorded trial evidence for pinned methods, and added an <code>autoLearn</code> scheduler switch; 3 files (+52).</td></tr><tr><td><code>b736389</code></td><td>JasonBuildAI</td><td>Restored methods navigation and exposed generation, auto-learn settings, trial-task creation, paired evaluation, application audit, and generation rollback; 6 files (+150/−35).</td></tr><tr><td><code>fa30e12</code></td><td>JasonBuildAI</td><td>Documented task pins, per-run applications, adoption generations, and the constrained 2+2 evolution flow in the Chinese and English design docs; 4 files (+12/−4).</td></tr><tr><td><code>0e1a034</code></td><td>JasonBuildAI</td><td>Added first-run state and readiness APIs; onboarding is required only when no state exists and no chat model is configured, with completed, skipped, and reset states; 4 files (+261).</td></tr><tr><td><code>97ed0e9</code></td><td>JasonBuildAI</td><td>Added the four-step <code>/welcome</code> wizard: provider and connection test, executor check, memory and proactive preferences, and entry into chat; saving a model binds the native executor; 9 files (+956/−18).</td></tr><tr><td><code>3e71086</code></td><td>JasonBuildAI</td><td>Exposed &quot;Needs you&quot;, &quot;Memory&quot;, &quot;Skills&quot;, and &quot;Mail&quot; in primary navigation and wired proactive and connection settings into settings; 3 files (+51/−2).</td></tr><tr><td><code>9445f61</code></td><td>JasonBuildAI</td><td>Presented methods as &quot;Skills&quot; in the UI while keeping the auditable method model underneath; 2 files (+16/−16).</td></tr><tr><td><code>9eae68a</code></td><td>JasonBuildAI</td><td>Scanned once at startup and every five minutes afterwards, debounced scans for task/approval/effect/source changes after two seconds, and kept the existing frequency and quiet-hour limits; 4 files (+112/−5).</td></tr><tr><td><code>9890560</code></td><td>JasonBuildAI</td><td>Added an in-app notification centre that turns pending approvals and proactive suggestions into readable reminders, with optional browser desktop notifications while the page is open and no promise after it closes; 8 files (+393/−3).</td></tr><tr><td><code>668aa3f</code></td><td>JasonBuildAI</td><td>Recalled memories per conversation during direct chat, reported the count through an SSE <code>memory</code> event, and let recall failure fall through without blocking the answer; 8 files (+193/−8).</td></tr><tr><td><code>0beb552</code></td><td>JasonBuildAI</td><td>Captured experience memory only at terminal task states, avoiding repeated writes from intermediate states; 2 files (+26/−5).</td></tr><tr><td><code>7b6b934</code></td><td>JasonBuildAI</td><td>Added a Feishu/Lark long-connection gateway with tenant-token caching, message parsing, image/file download, reconnect, allowlist, and status, plus 269 lines of gateway tests; 8 files (+1,314).</td></tr><tr><td><code>ac778a9</code></td><td>JasonBuildAI</td><td>Sent task state and one-time approval summaries to mapped conversations; <code>/approve</code> and <code>/reject</code> accept only allowlisted open_ids and match approval prefixes within the current conversation; 3 files (+261/−3).</td></tr><tr><td><code>3f663ab</code></td><td>JasonBuildAI</td><td>Added Feishu connection settings: encrypted App ID/Secret, open_id allowlist, Feishu/Lark domain, enablement, and status; 5 files (+335/−3).</td></tr><tr><td><code>522eabc</code></td><td>JasonBuildAI</td><td>Added mail-account storage and APIs for SMTP/IMAP host, port, TLS, account, and encrypted password, with connection test, update, and delete; 5 files (+1,113).</td></tr><tr><td><code>d4e7a8f</code></td><td>JasonBuildAI</td><td>Turned an SMTP-account outbox draft into a one-time send approval; the effect ledger sends after approval and stores a receipt, with an idempotency key, deterministic Message-ID, and an uncertain state instead of a blind resend; 8 files (+382/−52).</td></tr><tr><td><code>77a00db</code></td><td>JasonBuildAI</td><td>Synced the latest 20–50 INBOX messages read-only without marking them read and deduplicated them into Sources by Message-ID; sync defaults to 15 minutes and can be disabled per account; 6 files (+253/−4).</td></tr><tr><td><code>d0bf9ee</code></td><td>JasonBuildAI</td><td>Added the mail workspace with accounts, inbox, and compose views, supporting sync, synced-mail preview, draft creation, and an approval card with mail preview and no-recall notice; 8 files (+955/−12).</td></tr><tr><td><code>e949650</code></td><td>JasonBuildAI</td><td>Documented first run, the proactive loop, Feishu, and real mail in the English and Chinese READMEs, delivery status, and design docs, and updated the baseline to 61 files and 381 tests; 10 files (+114/−34).</td></tr></tbody></table><h2 id="boundaries-and-next-step" tabindex="-1">Boundaries and next step <a class="header-anchor" href="#boundaries-and-next-step" aria-label="Permalink to &quot;Boundaries and next step&quot;">​</a></h2><ul><li>Mail still writes to the local outbox by default; only an SMTP account enables a real-send approval. Real accounts, bounce and spam semantics, OAuth2, and the attachment picker UI are not manually accepted; IMAP reads only the latest 20–50 messages and never marks them read.</li><li>The Feishu long connection provides text messages and one-time approval commands, but it is not a mobile PWA, system push, or complete remote takeover. A real tenant, rate limits, reconnect behaviour, and a card-button option remain unaccepted, and nothing is pushed after the page closes.</li><li>Method auto-learning and 2+2 evidence now reach scheduling and audit, but long-term production comparisons, wrong-method drills, and candidate-quality data are still missing; generating a candidate is not the same as proving a method improved.</li><li>First run checks only models, executors, memory, and the proactive service; backup, safety, and data migration are not covered. A failed onboarding query or a non-root route does not force the wizard, which is a deliberate recovery path.</li><li>Proactive scans run every five minutes and react to domain events, but there is no system-level push after the page closes; notifications are reminders, and approval still goes through the same one-time approval chain.</li><li>The first-run API test is sensitive to startup latency and once hit a five-second timeout under parallel load; reruns passed, but the timeout margin still needs adjustment.</li><li>Real acceptance for phases 2–6 is unchanged: real mail/calendar, a Feishu tenant, the phone entrance, high-risk desktop actions, memory production comparisons, two-device switching, and weeks of continuous operation remain open.</li><li>The next stage continues closing real evidence along the <a href="/hearth-os/en/delivery/">delivery route</a> rather than adding entrances that only prove a page exists.</li></ul>',20)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
